import type OpenFin from '@openfin/core';

import type PageRoute from '@common/utils/route';

import { finName, finUUID } from './env';
import { currentOFIdentity, WindowIdentity } from './window';

const crossWinNavTopic = '__cross_window_navigation__';
const crossWinNavAction = 'navigate-window';

interface CrossWindowNavigationRequest {
    type: 'request';
    identity: OpenFin.Identity;
    route: string;
}

const getCrossWinNavId = (identity: OpenFin.Identity) => `${crossWinNavTopic}-${identity.uuid}-${identity.name}`;

let crossWinNavListener: (payload: CrossWindowNavigationRequest, identity: OpenFin.ProviderIdentity) => Promise<void>;

/**
 * Allow other OpenFin windows within a given list of applications
 * to navigate the current window to a different route.
 */
export async function enableCrossOFWindowNavigation(applicationUUIDs = [finUUID]): Promise<void> {
    const { navigate } = await import('./router');
    crossWinNavListener = async (payload, identity) => {
        if (
            applicationUUIDs.some((uuid) => uuid === identity.uuid) &&
            payload.identity.name === finName &&
            payload.identity.uuid === finUUID
        ) {
            await navigate(payload.route);
        }
    };

    const channelId = getCrossWinNavId(currentOFIdentity);
    const channel = await fin.InterApplicationBus.Channel.create(channelId);
    channel.register(crossWinNavAction, crossWinNavListener);
}

/**
 * Instruct another OpenFin window to navigate.
 * The target OpenFin window identity must have cross window navigation enabled.
 * To enable cross window navigation, see `enableCrossWindowNavigation`.
 */
export async function navigateOFWindow(identity: WindowIdentity, route: PageRoute | string): Promise<void> {
    const channelId = getCrossWinNavId(identity);
    const channel = await fin.InterApplicationBus.Channel.connect(channelId);

    // Await channel dispatch to ensure that the OF window has navigated before resolving
    // the promise returned by this function.
    await channel.dispatch(crossWinNavAction, { route, identity });

    await channel.disconnect();
}
